create table dm_private.learning_lessons(id uuid primary key default gen_random_uuid(),slug text unique not null check(slug~'^[a-z0-9]+(?:-[a-z0-9]+)*$'),exam text not null check(exam in('uceed','nid','nift','ceed')),topic text not null,title text not null check(char_length(title) between 5 and 160),summary text not null check(char_length(summary) between 10 and 500),body text not null check(char_length(body) between 20 and 50000),ordinal integer not null check(ordinal between 1 and 1000),published boolean not null default false,rights_confirmed boolean not null default false,created_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),unique(exam,topic,ordinal));
create table dm_private.learning_progress(user_id uuid not null references auth.users(id) on delete cascade,lesson_id uuid not null references dm_private.learning_lessons(id) on delete cascade,completed_at timestamptz not null default now(),primary key(user_id,lesson_id));
alter table dm_private.learning_lessons enable row level security; alter table dm_private.learning_progress enable row level security;
revoke all on dm_private.learning_lessons,dm_private.learning_progress from anon,authenticated;
create or replace function public.learning_catalog() returns jsonb language sql stable security definer set search_path=pg_catalog,dm_private as $$ select coalesce(jsonb_agg(jsonb_build_object('id',l.id,'slug',l.slug,'exam',l.exam,'topic',l.topic,'title',l.title,'summary',l.summary,'completed',p.lesson_id is not null) order by l.exam,l.topic,l.ordinal),'[]') from dm_private.learning_lessons l left join dm_private.learning_progress p on p.lesson_id=l.id and p.user_id=auth.uid() where auth.uid() is not null and l.published and l.rights_confirmed $$;
create or replace function public.read_learning_lesson(p_slug text) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,dm_private as $$ declare v jsonb; begin if auth.uid() is null then raise exception 'Sign in required'; end if; select jsonb_build_object('id',l.id,'slug',l.slug,'exam',l.exam,'topic',l.topic,'title',l.title,'summary',l.summary,'body',l.body,'completed',p.lesson_id is not null) into v from dm_private.learning_lessons l left join dm_private.learning_progress p on p.lesson_id=l.id and p.user_id=auth.uid() where l.slug=p_slug and l.published and l.rights_confirmed; if v is null then raise exception 'Lesson not found'; end if; return v; end $$;
create or replace function public.complete_learning_lesson(p_lesson_id uuid) returns void language plpgsql security definer set search_path=pg_catalog,dm_private as $$ begin if auth.uid() is null then raise exception 'Sign in required'; end if; if not exists(select 1 from dm_private.learning_lessons where id=p_lesson_id and published and rights_confirmed) then raise exception 'Lesson not found'; end if; insert into dm_private.learning_progress values(auth.uid(),p_lesson_id,now()) on conflict do nothing; end $$;
create or replace function public.admin_learning_lessons() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,dm_private as $$ begin if not public.is_dmocks_admin() then raise exception 'Admin access required'; end if; return(select coalesce(jsonb_agg(jsonb_build_object('id',id,'slug',slug,'exam',exam,'topic',topic,'title',title,'summary',summary,'body',body,'ordinal',ordinal,'published',published,'rightsConfirmed',rights_confirmed) order by exam,topic,ordinal),'[]') from dm_private.learning_lessons); end $$;
create or replace function public.admin_upsert_learning_lesson(p_id uuid,p_slug text,p_exam text,p_topic text,p_title text,p_summary text,p_body text,p_ordinal integer,p_publish boolean,p_rights_confirmed boolean) returns uuid language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$ declare v uuid:=coalesce(p_id,gen_random_uuid()); begin if not public.is_dmocks_admin() then raise exception 'Admin access required'; end if; if p_publish and not p_rights_confirmed then raise exception 'Rights confirmation is required'; end if; insert into dm_private.learning_lessons values(v,lower(trim(p_slug)),p_exam,trim(p_topic),trim(p_title),trim(p_summary),trim(p_body),p_ordinal,p_publish,p_rights_confirmed,auth.uid(),now()) on conflict(id) do update set slug=excluded.slug,exam=excluded.exam,topic=excluded.topic,title=excluded.title,summary=excluded.summary,body=excluded.body,ordinal=excluded.ordinal,published=excluded.published,rights_confirmed=excluded.rights_confirmed,updated_at=now(); return v; end $$;
revoke all on function public.learning_catalog(),public.read_learning_lesson(text),public.complete_learning_lesson(uuid),public.admin_learning_lessons(),public.admin_upsert_learning_lesson(uuid,text,text,text,text,text,text,integer,boolean,boolean) from public,anon;
grant execute on function public.learning_catalog(),public.read_learning_lesson(text),public.complete_learning_lesson(uuid),public.admin_learning_lessons(),public.admin_upsert_learning_lesson(uuid,text,text,text,text,text,text,integer,boolean,boolean) to authenticated;
